def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return float(max(0.0, bid))

    prev_bids = []
    urgent_prev_bids = []
    weak_prev_bids = []
    rich_count = 0
    desperate_count = 0

    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(float(pbid))
            else:
                weak_prev_bids.append(float(pbid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_urgent = max(urgent_prev_bids) if urgent_prev_bids else highest_prev
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    need = 0.0
    if hp <= 2:
        need += 1.0
    elif hp <= 4:
        need += 0.65
    elif hp <= 6:
        need += 0.35

    if no_water >= 2:
        need += 1.0
    elif no_water >= 1:
        need += 0.55

    if day >= 8:
        need += 0.2

    pressure_bid = highest_urgent + 2.0
    if pressure_bid < avg_prev + 1.0:
        pressure_bid = avg_prev + 1.0

    base = DAILY_SALARY * (0.28 + 0.42 * scarcity)

    if need >= 1.4:
        bid = max(base, pressure_bid, DAILY_SALARY * 0.95)
    elif need >= 0.8:
        bid = max(base, min(pressure_bid, DAILY_SALARY * 1.15), DAILY_SALARY * 0.72)
    elif scarcity >= 0.75:
        bid = max(base, min(highest_prev + 1.5, DAILY_SALARY * 0.95))
    elif supply >= 22:
        bid = DAILY_SALARY * 0.22
    elif supply >= 20:
        bid = DAILY_SALARY * 0.32
    else:
        bid = max(base, min(highest_prev * 0.72, DAILY_SALARY * 0.68))

    if rich_count >= 2 and scarcity >= 0.6 and need < 0.8:
        bid = min(bid, DAILY_SALARY * 0.45)

    if desperate_count >= 2 and need >= 0.8:
        bid = max(bid, highest_urgent + 3.0)

    reserve_target = DAILY_SALARY * max(0, 10 - day) * 0.38
    max_affordable = budget
    if budget > reserve_target and need < 1.4:
        max_affordable = max(0.0, budget - reserve_target * 0.35)

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no alive opponents, conserve
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.35)

    # Use yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Baseline: target a bid slightly above the median of yesterday bids
    if yesterday_bids:
        yesterday_bids_sorted = sorted(yesterday_bids)
        mid_idx = int(len(yesterday_bids_sorted) // 2)
        median_bid = yesterday_bids_sorted[mid_idx]
        target = median_bid + 3.0
    else:
        target = DAILY_SALARY * 0.55

    # Supply pressure: if supply is low, increase competitiveness; if high, reduce
    # supply in [15,25]
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # low supply => more aggressive
    supply_factor = 1.12 - 0.25 * supply_norm
    target *= supply_factor

    # HP-based risk control: with high hp, don't overpay
    hp = float(my_status['hp'])
    if hp >= 7:
        target *= 0.92
    elif hp >= 4:
        target *= 1.05
    else:
        target *= 1.25

    # Budget guardrails
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we've been without water too long, raise bid to avoid death spiral
    if no_water_days >= 2:
        target *= 1.18

    # Ensure bid does not exceed budget
    bid = min(budget, target)

    # Keep within reasonable bounds relative to salary
    min_bid = DAILY_SALARY * 0.25
    max_bid = min(budget, DAILY_SALARY * 0.95)
    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    # Final safety: if budget is tiny, bid whatever we can
    if budget <= 1.0:
        return max(0.0, budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    # Strategy: If HP is low, bid aggressively. Otherwise, bid slightly above market average.
    if my_status['hp'] <= 3:
        target_bid = min(my_status['budget'], DAILY_SALARY * 1.2)
    else:
        target_bid = min(my_status['budget'], max(avg_opp_bid * 0.95, DAILY_SALARY * 0.65))

    return float(target_bid)
